-- ============================================================================
-- AgriTabang — ADD-ON for the 92 practice farmers  (run AFTER 01_create_practice_farmers.sql)
--   1. profile photo for all 92 accounts
--   2. associations: LARFA / LIFA / none
--   3. crop insurance: New Registration and Renewal for some farmers
--   4. admin posts a P5,000 cash assistance announcement for CORN and CASSAVA farmers only
--      (farmers with other crops do NOT receive it and are not eligible)
--   5. 5 eligible farmers have applied (status Pending) -> they appear in the admin's Assistance Management
-- Only touches accounts farmer1..farmer92@agritabang.ph. Safe to run twice.
-- ============================================================================
begin;

-- the President-notification trigger (if you installed it) would send 60+ notices for this bulk update
do $$ begin execute 'alter table public.farmers disable trigger trg_notify_president_membership';
exception when undefined_object then null; end $$;

-- 1) profile photo ---------------------------------------------------------
update public.farmers f
   set photo_url = 'data:image/jpeg;base64,'
  from public.profiles p
 where p.id = f.id and p.email ~ '^farmer[0-9]+@agritabang\.ph$';

-- 2) associations ----------------------------------------------------------
insert into public.associations (name) values ('LARFA'), ('LIFA') on conflict (name) do nothing;
update public.farmers f
   set is_association_member = (v.assoc <> 'None'),
       association_id = (select a.id from public.associations a where a.name = v.assoc)
  from (values (1,'LARFA'),(2,'LARFA'),(3,'LARFA'),(4,'LARFA'),(5,'LIFA'),(6,'LIFA'),(7,'LIFA'),(8,'None'),(9,'None'),(10,'None'),(11,'LARFA'),(12,'LARFA'),(13,'LARFA'),(14,'LARFA'),(15,'LIFA'),(16,'LIFA'),(17,'LIFA'),(18,'None'),(19,'None'),(20,'None'),(21,'LARFA'),(22,'LARFA'),(23,'LARFA'),(24,'LARFA'),(25,'LIFA'),(26,'LIFA'),(27,'LIFA'),(28,'None'),(29,'None'),(30,'None'),(31,'LARFA'),(32,'LARFA'),(33,'LARFA'),(34,'LARFA'),(35,'LIFA'),(36,'LIFA'),(37,'LIFA'),(38,'None'),(39,'None'),(40,'None'),(41,'LARFA'),(42,'LARFA'),(43,'LARFA'),(44,'LARFA'),(45,'LIFA'),(46,'LIFA'),(47,'LIFA'),(48,'None'),(49,'None'),(50,'None'),(51,'LARFA'),(52,'LARFA'),(53,'LARFA'),(54,'LARFA'),(55,'LIFA'),(56,'LIFA'),(57,'LIFA'),(58,'None'),(59,'None'),(60,'None'),(61,'LARFA'),(62,'LARFA'),(63,'LARFA'),(64,'LARFA'),(65,'LIFA'),(66,'LIFA'),(67,'LIFA'),(68,'None'),(69,'None'),(70,'None'),(71,'LARFA'),(72,'LARFA'),(73,'LARFA'),(74,'LARFA'),(75,'LIFA'),(76,'LIFA'),(77,'LIFA'),(78,'None'),(79,'None'),(80,'None'),(81,'LARFA'),(82,'LARFA'),(83,'LARFA'),(84,'LARFA'),(85,'LIFA'),(86,'LIFA'),(87,'LIFA'),(88,'None'),(89,'None'),(90,'None'),(91,'LARFA'),(92,'LARFA')) as v(n, assoc), public.profiles p
 where p.id = f.id and p.email = 'farmer' || v.n || '@agritabang.ph';

-- 3) crop insurance (New Registration / Renewal is classified by the database itself) --
do $$
declare rec record; fid uuid; crop text; ar numeric; plant date; made int := 0;
begin
  for rec in select * from (values (1,'New Registration'),(4,'Renewal'),(7,'New Registration'),(10,'Renewal'),(13,'New Registration'),(16,'Renewal'),(19,'New Registration'),(22,'Renewal'),(25,'New Registration'),(28,'Renewal'),(31,'New Registration'),(34,'Renewal'),(37,'New Registration'),(40,'Renewal'),(43,'New Registration'),(46,'Renewal'),(49,'New Registration'),(52,'Renewal'),(55,'New Registration'),(58,'Renewal'),(61,'New Registration'),(64,'Renewal'),(67,'New Registration'),(70,'Renewal'),(73,'New Registration'),(76,'Renewal'),(79,'New Registration'),(82,'Renewal'),(85,'New Registration'),(88,'Renewal'),(91,'New Registration')) as t(n, kind) loop
    select p.id into fid from public.profiles p where p.email = 'farmer' || rec.n || '@agritabang.ph';
    continue when fid is null;
    continue when exists (select 1 from public.insurance_registrations i where i.farmer_id = fid);
    select cr.crop_name, cr.area, cr.planting_date into crop, ar, plant
      from public.crop_registrations cr where cr.farmer_id = fid order by cr.registered_at limit 1;
    continue when crop is null;

    if rec.kind = 'Renewal' then   -- last season's policy first, so this year's policy becomes a Renewal
      insert into public.insurance_registrations (farmer_id, crop_name, area, planting_date, status, registered_at, coverage_start_date, coverage_end_date)
      values (fid, crop, ar, plant - 365, 'Active', (plant - 365)::timestamptz, plant - 365, plant - 365 + 120);
    end if;
    insert into public.insurance_registrations (farmer_id, crop_name, area, planting_date, status, coverage_start_date, coverage_end_date)
    values (fid, crop, ar, plant, 'Active', plant, plant + 120);
    made := made + 1;
  end loop;
  raise notice 'Farmers with crop insurance added: %', made;
end $$;

-- 4) the admin's announcement: P5,000 cash, CORN and CASSAVA farmers only ---
insert into public.assistance_announcements (assistance_type, icon, title, body, deadline, audience, target_crops, posted_by)
select 'Cash Assistance', 'fa-hand-holding-dollar',
       '₱5,000 Cash Assistance for Corn and Cassava Farmers',
       'P5,000 cash assistance for Corn and Cassava farmers of Barangay Lindaban. (Practice announcement for testing.)',
       date '2026-12-31', 'crops', array['Corn','Cassava'],
       (select id from public.profiles where role = 'admin' order by created_at limit 1)
where not exists (select 1 from public.assistance_announcements where title = '₱5,000 Cash Assistance for Corn and Cassava Farmers');

-- 5) five eligible farmers apply -> they show up in the admin's Assistance Management as Pending
insert into public.assistance_records (farmer_id, assistance_type, value_description, status, announcement_id)
select p.id, 'Cash Aid', 'P5,000 cash assistance (practice application)', 'Pending', a.id
  from public.profiles p
 cross join (select id from public.assistance_announcements where title = '₱5,000 Cash Assistance for Corn and Cassava Farmers' limit 1) a
 where p.email in ('farmer1@agritabang.ph','farmer6@agritabang.ph','farmer27@agritabang.ph','farmer38@agritabang.ph','farmer53@agritabang.ph')
   and not exists (select 1 from public.assistance_records r where r.farmer_id = p.id and r.announcement_id = a.id);

do $$ begin execute 'alter table public.farmers enable trigger trg_notify_president_membership';
exception when undefined_object then null; end $$;
commit;
